std::future<Connection> conn = std::async(std::launch::deferred,
                                         [] { return dial(endpoint); });
// nothing acquired yet
Connection c = conn.get();   // dial runs here, once

class Session {
  std::optional<Connection> conn_;
public:
  Connection& connection() {
    if (!conn_) conn_.emplace(dial(endpoint));   // acquired on first use
    return *conn_;
  }
  void drop() { conn_.reset(); }                  // release, re-acquire later
};
